package com.hardcraft.mobs;
import java.nio.file.*;import java.sql.*;import java.util.*;
final class LootRepository{private final String url;LootRepository(Path p){url="jdbc:sqlite:"+p.toAbsolutePath();}void migrate(){try{Path p=Path.of(url.substring(12));Files.createDirectories(p.getParent());try(Connection c=open();Statement s=c.createStatement()){s.execute("CREATE TABLE IF NOT EXISTS hardcraft_mob_loot(entity_uuid TEXT NOT NULL,player_uuid TEXT NOT NULL,boss_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(entity_uuid,player_uuid))");}}catch(Exception e){throw new IllegalStateException("Mobs migration failed",e);}}synchronized boolean claim(UUID entity,UUID player,String boss){try(Connection c=open();PreparedStatement s=c.prepareStatement("INSERT OR IGNORE INTO hardcraft_mob_loot VALUES(?,?,?,?)")){s.setString(1,entity.toString());s.setString(2,player.toString());s.setString(3,boss);s.setLong(4,System.currentTimeMillis());return s.executeUpdate()==1;}catch(SQLException e){throw new IllegalStateException("Loot claim failed",e);}}private Connection open()throws SQLException{Connection c=DriverManager.getConnection(url);try(Statement s=c.createStatement()){s.execute("PRAGMA busy_timeout=5000");}return c;}}